6	function cli(label,args){let z=r.run(process.execPath,['bin/ai-writer.mjs',...args,'--project',P],label);if(z.exit_code!==0){console.error(z.stdout,z.stderr);throw Error('CLI failed '+label);}return r.json(label);}
7	const [mode,num,...rest]=process.argv.slice(2);const n=Number(num);
8	if(mode==='prepare'){
9	 const input=`${S}/plan-${n}.json`;const plan=JSON.parse(fs.readFileSync(input,'utf8'));
10	 const a=cli(`plan-${n}`,['plan','--input',input]);
11	 const c=cli(`context-${n}`,['context','--unit',String(n),'--max-chars','1500000']);write(`${S}/context-${n}.json`,c);
12	 const draft=`正文/${String(n).padStart(4,'0')}-${plan.title}.md`;
13	 const t=cli(`template-${n}`,['record-template','--unit',String(n),'--draft',draft]);write(`${S}/template-${n}.json`,t);
14	 console.log(JSON.stringify({plan:a,context_keys:Object.keys(c),template:t},null,2));
15	}else if(mode==='context-view'){
16	 const c=JSON.parse(fs.readFileSync(`${S}/context-${n}.json`,'utf8'));
17	 const slim=(v)=>typeof v==='string'?v.split('；截至第')[0].split('；保留至')[0].split('；历史有效知情')[0]:Array.isArray(v)?v.map(slim):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,slim(x)])):v;
18	 console.log(JSON.stringify(slim({unit:c.unit,revision:c.revision,plan:c.plan,outline:c.outline,snapshot:{characters:c.snapshot?.characters},continuity:{...c.continuity,author:Object.fromEntries(Object.entries(c.continuity?.author??{}).map(([id,v])=>[id,{type:v.type,statement:v.statement,truth:v.truth,status:v.status,due_unit:v.due_unit,custody:v.custody}]))},source_hashes:c.source_hashes}),null,2));
19	}else if(mode==='log'){
20	 const list=JSON.parse(fs.readFileSync(`${S}/${num}`,'utf8'));
21	 for(const x of list){let file=path.resolve(P,x.path);let b=fs.readFileSync(file);fs.appendFileSync(`${S}/reading.jsonl`,JSON.stringify({at:new Date().toISOString(),path:file,sha256:hash(file),range:`full:1-${b.toString('utf8').split(/\r?\n/).length}`,purpose:x.purpose,method:'FastCtx complete text read by model; hash receipt after read'})+'\n','utf8');}
22	 console.log('Logged actual completed reads:',list.length);
23	}else if(mode==='finish'){
24	 const raw=JSON.parse(fs.readFileSync(`${S}/template-${n}.json`,'utf8'));
